mapper.select:
SELECT 'LOCATION' AS type, l.id, l.name AS text, c.name AS subtitle FROM location l INNER JOIN campus c ON c.id = l.campus_id AND c.status = 1 INNER JOIN city ci ON ci.id = c.city_id AND ci.status = 1 WHERE l.status = 1
AND ( l.name LIKE CONCAT('%', #{keyword}, '%') OR l.address LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY l.sort_order, l.id LIMIT #{limit}

mapper.update:
UPDATE location
campus_id = #{value.campusId}, name = #{value.name}, category_code = #{value.categoryCode}, address = #{value.address}, longitude = #{value.longitude}, latitude = #{value.latitude}, cover_key = #{value.coverKey}, description = #{value.description}, sort_order = #{value.sortOrder}, status = #{value.status}, updated_at = #{updatedAt}
WHERE id = #{id}
